#include <bits/stdc++.h>
using namespace std;using ll=long long;
struct DSU{vector<int>p,s;DSU(int n):p(n),s(n,1){iota(p.begin(),p.end(),0);}int f(int v){while(v!=p[v])v=p[v]=p[p[v]];return v;}bool un(int a,int b){a=f(a);b=f(b);if(a==b)return false;if(s[a]<s[b])swap(a,b);p[b]=a;s[a]+=s[b];return true;}};int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m,q;cin>>n>>m>>q;vector<tuple<ll,int,int,int>>e;vector<tuple<int,int,ll>>orig(m);for(int i=0;i<m;i++){auto &[u,v,w]=orig[i];cin>>u>>v>>w;--u;--v;e.push_back({w,u,v,i});}sort(e.begin(),e.end());DSU ds(n);vector<vector<pair<int,ll>>>g(n);ll total=0;for(auto[w,u,v,id]:e)if(ds.un(u,v)){total+=w;g[u].push_back({v,w});g[v].push_back({u,w});}int K=bit_width((unsigned)n);vector<vector<int>>up(K,vector<int>(n));vector<vector<ll>>mx(K,vector<ll>(n,LLONG_MIN));vector<int>p(n,-1),d(n),order{0};p[0]=0;for(size_t i=0;i<order.size();i++){int v=order[i];for(auto[u,w]:g[v])if(u!=p[v]){p[u]=v;d[u]=d[v]+1;mx[0][u]=w;order.push_back(u);}}up[0]=p;for(int k=1;k<K;k++)for(int v=0;v<n;v++){int mid=up[k-1][v];up[k][v]=up[k-1][mid];mx[k][v]=max(mx[k-1][v],mx[k-1][mid]);}auto pathmax=[&](int u,int v){ll ans=LLONG_MIN;if(d[u]<d[v])swap(u,v);int delta=d[u]-d[v];for(int k=0;k<K;k++)if(delta>>k&1){ans=max(ans,mx[k][u]);u=up[k][u];}if(u!=v){for(int k=K-1;k>=0;k--)if(up[k][u]!=up[k][v]){ans=max({ans,mx[k][u],mx[k][v]});u=up[k][u];v=up[k][v];}ans=max({ans,mx[0][u],mx[0][v]});}return ans;};while(q--){int id;cin>>id;auto[u,v,w]=orig[id-1];cout<<total+w-pathmax(u,v)<<'\n';}}
